use vstd::prelude::*;

verus! {
    // Linear search for the first occurrence of e in a.
    //
    // Specification:
    //   - Requires that there is at least one index j < a.len() with a[j] == e.
    //   - Returns n such that:
    //       * n < a.len()
    //       * a[n] == e
    //       * for all i < n, a[i] != e
    pub fn linear_search(a: &Vec<i32>, e: i32) -> (n: usize)
        requires
            exists |j: usize| j < a.len() && a[j] == e,
        ensures
            n < a.len(),
            a[n] == e,
            forall |i: usize| i < n ==> a[i] != e,
    {
        let len = a.len();
        let mut i: usize = 0;

        // We maintain:
        //   1) i <= len
        //   2) exists k in [i, len) with a[k] == e
        //   3) for all j < i, a[j] != e
        // And we decrease (len - i) each iteration.
        while i < len && a[i] != e
            invariant
                i <= len,
                exists |k: usize| i <= k && k < len && a[k] == e,
                forall |j: usize| j < i ==> a[j] != e,
            decreases(len - i),
        {
            let old_i = i;
            // We know a[old_i] != e and there was some k >= old_i with a[k] == e.
            // We prove that there is some k >= old_i + 1 with a[k] == e, to re-establish the exists invariant.
            assert(exists |k: usize| old_i + 1 <= k && k < len && a[k] == e) by {
                // pick a witness for the old existential
                let witness: usize = choose |k: usize| old_i <= k && k < len && a[k] == e;
                // show witness cannot be old_i
                assert(witness != old_i) by {
                    assert(a[witness] == e);       // from the choose condition
                    assert(a[old_i] != e);         // from the loop condition
                }
                // therefore witness >= old_i + 1
                assert(witness >= old_i + 1);
            }
            // advance the index
            i = old_i + 1;
        }

        // At loop exit: !(i < len && a[i] != e)
        // Combined with the invariant that some occurrence remains in [i, len),
        // we conclude i < len and a[i] == e.
        assert(i < len);
        assert(a[i] == e);

        i
    }
}

